import React from 'react';
import { BrowserRouter as Router, Route, Routes, Link } from 'react-router-dom';
import ClienteList from './components/Clientes/ClienteList';
import CreateCliente from './components/Clientes/CreateCliente';
import ProjetoList from './components/Projetos/ProjetoList';  // Importando Projetos
import CreateProjeto from './components/Projetos/CreateProjeto';  // Importando Criar Projeto
import AtividadeList from './components/Atividades/AtividadeList';  // Importando Atividades
import CreateAtividade from './components/Atividades/CreateAtividade';  // Importando Criar Atividade
import './components/Clientes/ClienteManagement.css'; // Importando o CSS

const App = () => {
  return (
    <Router>
      <div className="cliente-management">
        <h2>Gestão de Clientes</h2>

        {/* Links de Navegação */}
        <div className="navigation-links">
          <Link to="/clientes">Clientes</Link>
          <Link to="/projetos">Projetos</Link>
          <Link to="/atividades">Atividades</Link>
        </div>

        {/* Rotas do React Router */}
        <Routes>
          <Route path="/clientes" element={<ClienteList />} />
          <Route path="/clientes/criar" element={<CreateCliente />} />
          <Route path="/clientes/:clienteId/projetos" element={<ProjetoList />} />
          <Route path="/clientes/:clienteId/projetos/criar" element={<CreateProjeto />} />
          <Route path="/clientes/:clienteId/projetos/:projetoId/atividades" element={<AtividadeList />} />
          <Route path="/clientes/:clienteId/projetos/:projetoId/atividades/criar" element={<CreateAtividade />} />
        </Routes>
      </div>
    </Router>
  );
};

export default App;
